// Vercel serverless function: fetches the latest near-real-time VIIRS fire detections
// over Argentina from NASA FIRMS and returns fire-active H3 cell-days, so the app can
// compare "right now" with 25 years of harmonized history.
// The FIRMS MAP_KEY stays on the server (env var FIRMS_MAP_KEY) and is never sent to browsers.
import { latLngToCell } from 'h3-js'

// hexagons with persistent gas flares / industrial heat in the archive (type 1-3 on 20+ days)
// BEGIN STATIC_CELLS (generated by pipeline/build_data.py)
const STATIC_CELLS: string[] = ["85a94467fffffff", "85a9447bfffffff", "85a951cbfffffff", "85a96103fffffff", "85a9610ffffffff", "85a96167fffffff", "85a9616ffffffff", "85a96177fffffff", "85a96303fffffff", "85a96317fffffff", "85a963c7fffffff", "85a963cffffffff", "85a96523fffffff", "85a9652ffffffff", "85a96537fffffff", "85a96993fffffff", "85a96e0bfffffff", "85a96e7bfffffff", "85a96ec3fffffff", "85a96ed7fffffff", "85b24197fffffff", "85b2437bfffffff", "85b2452ffffffff", "85b24537fffffff", "85b24937fffffff", "85b24987fffffff", "85b24997fffffff", "85b249a3fffffff", "85b249b3fffffff", "85b249bbfffffff", "85b24d27fffffff", "85b24d37fffffff", "85b25493fffffff", "85b260affffffff", "85b2652bfffffff", "85b2692ffffffff", "85b269a7fffffff", "85b269b7fffffff", "85b26acbfffffff", "85b26acffffffff", "85b26ad3fffffff", "85b26adbfffffff", "85b271dbfffffff", "85b275c3fffffff", "85b275cffffffff", "85b2c863fffffff", "85b2c867fffffff", "85b2cb23fffffff", "85b2cb2bfffffff", "85b2cb67fffffff", "85b2cb77fffffff", "85b2cb9bfffffff", "85b2ee33fffffff", "85b2eeb3fffffff", "85b34297fffffff", "85b35ccffffffff", "85c2280bfffffff", "85c22d23fffffff", "85c22d2ffffffff", "85c2c91bfffffff", "85c2c957fffffff", "85c2c96bfffffff", "85c2c97bfffffff", "85c2c993fffffff", "85c2c99bfffffff", "85c2c9c3fffffff", "85c2c9c7fffffff", "85c2c9cffffffff", "85c2c9d7fffffff", "85c2ca57fffffff", "85c2ca6bfffffff", "85c2ca7bfffffff", "85c2cacffffffff", "85c2cb27fffffff", "85c2cb37fffffff", "85c2cba3fffffff", "85c2cbaffffffff", "85c2cbb3fffffff", "85c2cd27fffffff", "85c2cd2bfffffff", "85c2cd37fffffff", "85c2cd67fffffff", "85c2cda7fffffff", "85c2cdaffffffff", "85c2cdb7fffffff", "85c2e237fffffff", "85c2e2affffffff", "85c2e317fffffff", "85c2e3c7fffffff", "85c2e3dbfffffff", "85c2e863fffffff", "85c2e86ffffffff", "85c2ea97fffffff", "85c2eaa7fffffff", "85c2eb17fffffff", "85c2eb83fffffff", "85c2eb8bfffffff", "85c2eb9bfffffff", "85c2eba3fffffff", "85c2ebabfffffff", "85c2ebb7fffffff", "85c2ebbbfffffff", "85c2ebd3fffffff", "85c2ebd7fffffff", "85c2ee53fffffff", "85c2ee63fffffff", "85c2eecbfffffff", "85c32ba7fffffff", "85c34a07fffffff", "85c34b77fffffff", "85c35053fffffff", "85c350cffffffff", "85c36413fffffff", "85c36417fffffff", "85c36483fffffff", "85c36487fffffff", "85c3648bfffffff", "85c3648ffffffff", "85c36493fffffff", "85c36497fffffff", "85c3649bfffffff", "85c364c3fffffff", "85c364c7fffffff", "85c364cbfffffff", "85c364cffffffff", "85c364d3fffffff", "85c364d7fffffff", "85c364dbfffffff", "85c3658bfffffff", "85c36593fffffff", "85c365d7fffffff", "85c366affffffff", "85c376d3fffffff", "85ce851bfffffff", "85ce9357fffffff", "85ce9a43fffffff", "85ce9a53fffffff", "85ce9a57fffffff", "85ce9ad3fffffff", "85ce9e47fffffff", "85ce9e4bfffffff", "85ce9e6bfffffff", "85ce9e73fffffff", "85ce9e7bfffffff", "85ce9ecffffffff", "85cf9137fffffff", "85cf9ccbfffffff", "85cf9ccffffffff", "85cf9cd3fffffff", "85cf9e17fffffff", "85df4d83fffffff", "85df6b63fffffff", "85df6b77fffffff", "85df6b7bfffffff"]
// END STATIC_CELLS
const STATIC = new Set<string>(STATIC_CELLS)

const BBOX = '-74,-56,-53,-21' // west,south,east,north around Argentina
const DAYS = 5 // FIRMS area API allows 1-5 days
const SOURCE = 'VIIRS_NOAA20_NRT' // NOAA-20 calibrates ~1:1 to S-NPP (slope 0.99 in our fit)

export async function GET() {
  const key = process.env.FIRMS_MAP_KEY
  if (!key) {
    return Response.json({ ok: false, error: 'FIRMS_MAP_KEY is not set on the server' }, { status: 503 })
  }
  try {
    const url = `https://firms.modaps.eosdis.nasa.gov/api/area/csv/${key}/${SOURCE}/${BBOX}/${DAYS}`
    const r = await fetch(url)
    const text = await r.text()
    if (!r.ok || !text.startsWith('latitude')) {
      return Response.json({ ok: false, error: `FIRMS responded: ${text.slice(0, 120)}` }, { status: 502 })
    }
    const [head, ...lines] = text.trim().split('\n')
    const cols = head.split(',')
    const iLat = cols.indexOf('latitude'), iLon = cols.indexOf('longitude'), iDate = cols.indexOf('acq_date')
    const iConf = cols.indexOf('confidence'), iType = cols.indexOf('type')
    const seen = new Set<string>()
    let detections = 0
    let removedStatic = 0
    let first = '9999', last = '0000'
    for (const line of lines) {
      const c = line.split(',')
      if (iType >= 0 && c[iType] && c[iType] !== '0') continue
      if (iConf >= 0 && c[iConf] === 'l') continue
      detections++
      const d = c[iDate]
      if (d < first) first = d
      if (d > last) last = d
      const cell = latLngToCell(+c[iLat], +c[iLon], 5)
      if (STATIC.has(cell)) { removedStatic++; continue }
      seen.add(`${cell}|${d}`)
    }
    const cellDays: [string, string][] = Array.from(seen, (s) => s.split('|') as [string, string])
    return Response.json(
      { ok: true, source: SOURCE, days: DAYS, from: first, to: last, detections, removedStatic, cellDays, fetched: new Date().toISOString() },
      { headers: { 'Cache-Control': 's-maxage=1800, stale-while-revalidate=3600' } },
    )
  } catch (e) {
    return Response.json({ ok: false, error: String(e) }, { status: 500 })
  }
}
